INSERT INTO formulacion_144
 (id, formulario_id, nombre_borrador, anio, linea_estrategica, objetivo, estrategia, motor_desarrollo, proyecto, meta_resultado, ponderacion_proyectos, actividad_proyecto, ponderacion_actividades, responsable_formulacion, id_indicador, gestionado_facultades, nombre_indicador, formula_medicion, frecuencia_medicion, unidad_medida, tipo_medicion, descripcion_indicador, planes_institucionales, linea_base_meta, anio_base_meta, meta_s1, meta_s2, meta_programada, meta_ejecutada, porcentaje_avance, semestre1_seguimiento, semestre2_seguimiento, logros, limites, observacion_estado, acciones_fortalecimiento, estado_formulacion, estado_seguimiento, solicitud_estado_formulacion, solicitud_estado_seguimiento, semaforo_etapa_formulacion, semaforo_etapa_seguimiento, semaforo_rechazo_etapa_formulacion, semaforo_rechazo_etapa_seguimiento, fecha_publicacion_formulacion, creado_por)
VALUES
(@base+1, @formulario, 'Centro de Lenguas Extranjeras constituido', 2026, 'Impacto regional, nacional e internacional desde la extensión y proyección social', 'Coadyuvar con el desarrollo económico, social, cultural y ambiental a nivel regional, nacional e internacional; mediante la extensión y proyección social articulada con la investigación, creación, formación, innovación y transferencia tecnológica, que permita una interacción e integración permanente, amplia y diversa con el estado, la empresa y la sociedad.', '3. Contribuir desde lo académico, investigativo, extensión y proyección social en el tratamiento y resolución de temáticas de interés mediante el asesoramiento, análisis, formación de factores claves para la sociedad.', 'Educación continua y formación avanzada con enfoque global', 'Fortalecimiento de los programas de educación continua con perinencia regional, nacional e internacional a través de la modernización de los procesos', 'Mejoramiento de la oferta de programas de educación continua, con 1 Centro de Lenguas extranjeras, 5 ambientes de aprendizaje innovadores implementados, 2.300 programas de educación continua ejecutadas en distintas modalidalidades (presencial, semipresencial, virtual y a distancia), 35 con enfoque diferencial, 12 con componente internacional y 130 convenios con  entidades del sector público y privado', 18.00, 'Constituir el centro de lenguas nativas y extranjeras', 20.00, 'Dpto. de Extens. y Proy. Social', 'PDI', '0', 'Centro de Lenguas Extranjeras constituido', 'Centro de Lenguas Extranjeras constituido', 'Anual', 'Porcentaje', 'Último valor reportado', 'Para el 2026 seria la radicación, (Diseño, retroalimentación y ajustes), pendiente por revisión interna (jefe Dpto)', '[]', '33%', 33, '0%', '33%', '33.00', '0.00', 0.00, 0.00, NULL, 'Se logró la formulación y estructuración total del documento técnico y el proyecto de fundamentación requerido para la constitución legal del Centro de Lenguas Extranjeras (CLE).\n\nAnte la contingencia de infraestructura, se radicó formalmente la solicitud de concepto técnico ante la Oficina de Planeación de la Universidad del Atlántico, buscando viabilizar las alternativas de sede.', 'Las sedes alternas donde opera temporalmente el programa cuentan con un subsuelo catalogado como de uso comercial y no educativo, lo que constituye un impedimento legal y normativo insalvable para radicar la solicitud de creación formal del Centro ante las instancias correspondientes.\n\nEl proceso se encuentra condicionado y detenido debido a que, a la fecha de corte de este reporte, la Oficina de Planeación no ha emitido la respuesta ni las directrices institucionales solicitadas sobre el concepto técnico de infraestructura.', 'Se advierte que el indicador se mantendrá en estado de suspensión técnica mientras la Universidad no defina una sede física que cumpla con los requisitos de ley para el uso educativo. No es un retraso por gestión del equipo del CLE, sino un factor externo de fuerza mayor derivado de la remodelación de la Sede Centro.', 'Gestionar una reunión de carácter urgente con el equipo técnico de la Oficina de Planeación para agilizar la emisión del concepto y evaluar alternativas viables (como una asignación provisional de espacios en sedes autorizadas o un aval condicionado a la entrega de la Sede Centro).\n\nAdelantar la revisión y organización de todos los demás requisitos obligatorios para la constitución del centro, de modo que una vez se resuelva el factor sede, la radicación del proyecto ante el Consejo Superior o Académico sea inmediata.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+2, @formulario, 'Oferta de programas de educación continua en modalidades (presencial, semipresencial, virtual y a distancia)', 2026, 'Impacto regional, nacional e internacional desde la extensión y proyección social', 'Coadyuvar con el desarrollo económico, social, cultural y ambiental a nivel regional, nacional e internacional; mediante la extensión y proyección social articulada con la investigación, creación, formación, innovación y transferencia tecnológica, que permita una interacción e integración permanente, amplia y diversa con el estado, la empresa y la sociedad.', '6. Favorecer la proyección laboral de los egresados mediante el fortalecimiento de conocimientos y competencias requeridas para el contexto global.', 'Educación continua y formación avanzada con enfoque global', 'Fortalecimiento de los programas de educación continua con perinencia regional, nacional e internacional a través de la modernización de los procesos', 'Mejoramiento de la oferta de programas de educación continua, con 1 Centro de Lenguas extranjeras, 5 ambientes de aprendizaje innovadores implementados, 2.300 programas de educación continua ejecutadas en distintas modalidalidades (presencial, semipresencial, virtual y a distancia), 35 con enfoque diferencial, 12 con componente internacional y 130 convenios con  entidades del sector público y privado', 18.00, 'Impulsar la oferta de programas de educación continua en modalidad presencial ejecutadas', 20.00, 'Dpto. de Extens. y Proy. Social', 'PDI', '1', 'Oferta de programas de educación continua en modalidades (presencial, semipresencial, virtual y a distancia)', 'N° de programas de educación continua ejecutadas en distintas modalidades (presencial, semipresencial, virtual y a distancia)', 'Semestral', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Programas de educacion continua desarrollados en distintas modalidades.', '[]', '97', 60, '0', '60', '60.00', '40.00', 66.67, 40.00, NULL, 'Durante el primer semestre se desarrolló una oferta académica diversificada con 31 programas en diferentes modalidades, fortaleciendo el acceso de distintos públicos y ampliando la capacidad institucional para responder a las necesidades de formación continua. Se consolidaron procesos administrativos y académicos que facilitaron la apertura y seguimiento de los programas.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+3, @formulario, 'Oferta de programas de educación continua con componente internacional', 2026, 'Impacto regional, nacional e internacional desde la extensión y proyección social', 'Coadyuvar con el desarrollo económico, social, cultural y ambiental a nivel regional, nacional e internacional; mediante la extensión y proyección social articulada con la investigación, creación, formación, innovación y transferencia tecnológica, que permita una interacción e integración permanente, amplia y diversa con el estado, la empresa y la sociedad.', '6. Favorecer la proyección laboral de los egresados mediante el fortalecimiento de conocimientos y competencias requeridas para el contexto global.', 'Educación continua y formación avanzada con enfoque global', 'Fortalecimiento de los programas de educación continua con perinencia regional, nacional e internacional a través de la modernización de los procesos', 'Mejoramiento de la oferta de programas de educación continua, con 1 Centro de Lenguas extranjeras, 5 ambientes de aprendizaje innovadores implementados, 2.300 programas de educación continua ejecutadas en distintas modalidalidades (presencial, semipresencial, virtual y a distancia), 35 con enfoque diferencial, 12 con componente internacional y 130 convenios con  entidades del sector público y privado', 18.00, 'Impulsar la oferta de programas de educación continua con componente internacional', 15.00, 'Dpto. de Extens. y Proy. Social', 'PDI', '1', 'Oferta de programas de educación continua con componente internacional', 'N° de programas con componente internacional', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Programas de educacion continua que se caracterizan por contenido con componente internacional o docente/estudiante de talla internacional. (Justificado en formato correspondiente)', '[]', '11', 3, '0', '3', '3.00', '10.00', 333.33, 10.00, NULL, 'Durante el periodo evaluado se desarrollaron 6 programas de educación continua con componente internacional, incorporando contenido con enfoque globalizado, conforme a los criterios establecidos para este indicador. Con este resultado se superó ampliamente la meta propuesta para la vigencia, fortaleciendo la internacionalización de la oferta académica y promoviendo escenarios de intercambio de conocimientos y buenas prácticas con enfoque global.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+4, @formulario, 'Oferta de programas de educación continua con enfoque diferencial y/o capacidades diversas', 2026, 'Impacto regional, nacional e internacional desde la extensión y proyección social', 'Coadyuvar con el desarrollo económico, social, cultural y ambiental a nivel regional, nacional e internacional; mediante la extensión y proyección social articulada con la investigación, creación, formación, innovación y transferencia tecnológica, que permita una interacción e integración permanente, amplia y diversa con el estado, la empresa y la sociedad.', '6. Favorecer la proyección laboral de los egresados mediante el fortalecimiento de conocimientos y competencias requeridas para el contexto global.', 'Educación continua y formación avanzada con enfoque global', 'Fortalecimiento de los programas de educación continua con perinencia regional, nacional e internacional a través de la modernización de los procesos', 'Mejoramiento de la oferta de programas de educación continua, con 1 Centro de Lenguas extranjeras, 5 ambientes de aprendizaje innovadores implementados, 2.300 programas de educación continua ejecutadas en distintas modalidalidades (presencial, semipresencial, virtual y a distancia), 35 con enfoque diferencial, 12 con componente internacional y 130 convenios con  entidades del sector público y privado', 18.00, 'Impulsar la oferta de programas de educación continua con enfoque diferencial y/o capacidades diversas', 10.00, 'Dpto. de Extens. y Proy. Social', 'PDI', '1', 'Oferta de programas de educación continua con enfoque diferencial y/o capacidades diversas', 'N° de programas de educación continua con enfoque diferencial y/o capacidades diversas implementados', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Programas de educación continua implementados con enfoque diferencial y/o para capacidades diversas. El enfoque diferencial considera las necesidades, características, intereses y contextos específicos de diversos grupos poblacionales, mientras que la atención a capacidades diversas abarca las diferentes habilidades, talentos y ritmos de aprendizaje individuales.(Vinculacion de poblacion con estas caracteristicas y contenido)', '[]', '7', 6, '0', '6', '6.00', '5.00', 83.33, 5.00, NULL, 'Se implementaron 5 programas con enfoque diferencial, incorporando estrategias orientadas a favorecer la inclusión, la equidad y la atención de poblaciones con necesidades específicas de aprendizaje.', 'Aunque existe avance en la implementación de este enfoque, aún es necesario ampliar la cobertura y diversificar la oferta dirigida a poblaciones con características particulares.', '', 'Fortalecer el diseño curricular con criterios de accesibilidad e inclusión, promover procesos de sensibilización con los equipos académicos y generar nuevas propuestas formativas dirigidas a poblaciones con capacidades diversas y grupos priorizados.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+5, @formulario, 'Oferta de programas de educación continua basado en las necesidades específicas de entidades del sector público y/o privado', 2026, 'Impacto regional, nacional e internacional desde la extensión y proyección social', 'Coadyuvar con el desarrollo económico, social, cultural y ambiental a nivel regional, nacional e internacional; mediante la extensión y proyección social articulada con la investigación, creación, formación, innovación y transferencia tecnológica, que permita una interacción e integración permanente, amplia y diversa con el estado, la empresa y la sociedad.', '6. Favorecer la proyección laboral de los egresados mediante el fortalecimiento de conocimientos y competencias requeridas para el contexto global.', 'Educación continua y formación avanzada con enfoque global', 'Fortalecimiento de los programas de educación continua con perinencia regional, nacional e internacional a través de la modernización de los procesos', 'Mejoramiento de la oferta de programas de educación continua, con 1 Centro de Lenguas extranjeras, 5 ambientes de aprendizaje innovadores implementados, 2.300 programas de educación continua ejecutadas en distintas modalidalidades (presencial, semipresencial, virtual y a distancia), 35 con enfoque diferencial, 12 con componente internacional y 130 convenios con  entidades del sector público y privado', 18.00, 'Impulsar la oferta de programas de educación continua en convenio con entidades del sector público y/o privado', 10.00, 'Dpto. de Extens. y Proy. Social', 'PDI', '1', 'Oferta de programas de educación continua basado en las necesidades específicas de entidades del sector público y/o privado', 'N° de programas de educación continua realizados en convenio con entidades del sector público y/o privado', 'Semestral', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Programas de educacion continua realizado en convenios con entidades de sector publico y privado, incluye los programas de Cursos de Lenguas extranjeras a nivel regional (Kids, Juniors, Young y Adults)', '[]', '11', 5, '0', '5', '5.00', '0.00', 0.00, 0.00, NULL, 'El cumplimiento de este indicador depende directamente de la suscripción de convenios, contratos o acuerdos interinstitucionales que permitan diseñar y ejecutar programas de formación ajustados a las necesidades específicas de las entidades externas. Durante el semestre no se concretaron este tipo de vinculaciones debido a la vigencia de la Ley de Garantias.', '', 'Para el segundo semestre se debera fortalecer la gestión comercial e institucional para la consecución de convenios con entidades públicas y privadas, promover la identificación de necesidades de capacitación a la medida y consolidar alianzas estratégicas que permitan ampliar la oferta de programas especializados y alcanzar la meta establecida durante el segundo semestre.', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+6, @formulario, 'Oferta de cursos de CLE en modalidad (Presencial, semipresencial, virtual y a distancia)', 2026, 'Impacto regional, nacional e internacional desde la extensión y proyección social', 'Coadyuvar con el desarrollo económico, social, cultural y ambiental a nivel regional, nacional e internacional; mediante la extensión y proyección social articulada con la investigación, creación, formación, innovación y transferencia tecnológica, que permita una interacción e integración permanente, amplia y diversa con el estado, la empresa y la sociedad.', '6. Favorecer la proyección laboral de los egresados mediante el fortalecimiento de conocimientos y competencias requeridas para el contexto global.', 'Educación continua y formación avanzada con enfoque global', 'Fortalecimiento de los programas de educación continua con perinencia regional, nacional e internacional a través de la modernización de los procesos', 'Mejoramiento de la oferta de programas de educación continua, con 1 Centro de Lenguas extranjeras, 5 ambientes de aprendizaje innovadores implementados, 2.300 programas de educación continua ejecutadas en distintas modalidalidades (presencial, semipresencial, virtual y a distancia), 35 con enfoque diferencial, 12 con componente internacional y 130 convenios con  entidades del sector público y privado', 18.00, 'Impulsar la oferta de programas de educación continua en convenio con entidades del sector público y/o privado', 10.00, 'Dpto. de Extens. y Proy. Social', 'PA', '0', 'Oferta de cursos de CLE en modalidad (Presencial, semipresencial, virtual y a distancia)', 'N° de cursos CLE en distintas modalidades', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Numero de cursos CLE, los cuales incluyen los numeros de grupos existentes por curso en distintas modalidades.', '[]', '717', 450, '0', '450', '450.00', '334.00', 74.22, 334.00, NULL, 'A pesar de la contingencia de infraestructura, se logró ofertar y ejecutar 333 cursos durante el semestre 2026-1, lo que representa un 74% de cumplimiento de la meta anual (450) en solo el primer periodo del año.\n\nSe gestionó y coordinó con éxito el traslado y la operación simultánea de los cursos en cinco (5) sedes alternas, descentralizando la oferta académica sin suspender los servicios del CLE.\n\nAunque la línea base histórica del programa es alta (717), la cifra alcanzada en este periodo demuestra resiliencia operativa y el mantenimiento de una cobertura robusta en condiciones extraordinarias.', 'La fragmentación de la oferta en cinco sedes distintas generó complejidades en el control administrativo, la supervisión docente y la unificación de los procesos institucionales que habitualmente se centralizan en la Sede Centro.\n\nEl traslado imprevisto alteró las rutinas de desplazamiento de estudiantes y docentes, limitando el acceso óptimo a los recursos físicos y tecnológicos habituales de la Sede Centro de la Universidad del Atlántico.', 'Es imperativo advertir que la fatiga acumulada por la dispersión geográfica y los problemas de movilidad experimentados por la comunidad académica en el semestre 2026-1 proyectan un riesgo latente de deserción o disminución de la matrícula para el semestre 2026-2.', 'Se sugiere implementar un plan de comunicación prioritario y estrategias de fidelización/retención de estudiantes de cara al próximo semestre, así como evaluar el estado y los tiempos de entrega de la remodelación de la Sede Centro para dar certezas a la comunidad estudiantil.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+7, @formulario, 'Proyectos de extensión y proyección social remunerados en alianza con el sector público y/o privado', 2026, 'Impacto regional, nacional e internacional desde la extensión y proyección social', 'Coadyuvar con el desarrollo económico, social, cultural y ambiental a nivel regional, nacional e internacional; mediante la extensión y proyección social articulada con la investigación, creación, formación, innovación y transferencia tecnológica, que permita una interacción e integración permanente, amplia y diversa con el estado, la empresa y la sociedad.', '1. Promover la extensión y la proyección social como medio de vinculación de la universidad con la sociedad, en sinergia con el sector productivo para responder a sus demandas.', 'Articulación con el sector productivo y sociedad', 'Gestión de alianzas, convenios y proyectos para el fomento del desarrollo sostenible según la agenda (ODS), regional e internacional', 'Concretar al menos 150 proyectos de extensión y proyección social remunerados con el sector público y/o privado a través de la gestión de alianzas y convenios a nivel nacional e internacional.', 15.00, 'Promover la oferta institucional  para la prestación de bienes y servicios al sector  público y/o privado e impactar de manera pertinente el entorno', 20.00, 'Dpto. de Extens. y Proy. Social', 'PDI', '0', 'Proyectos de extensión y proyección social remunerados en alianza con el sector público y/o privado', 'N° de proyectos de extensión y proyección social suscritos con el sector público y/o privado', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Proyectos de extensión y proyección social remunerados en alianza con el sector público y/o privado, muy orientados a los de consultoria', '[]', '8', 1, '0', '1', '1.00', '0.00', 0.00, 0.00, NULL, '', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+8, @formulario, 'Tasa de variación de ingresos del CICIT y PTC para la vigencia de 10 años', 2026, 'Impacto regional, nacional e internacional desde la extensión y proyección social', 'Coadyuvar con el desarrollo económico, social, cultural y ambiental a nivel regional, nacional e internacional; mediante la extensión y proyección social articulada con la investigación, creación, formación, innovación y transferencia tecnológica, que permita una interacción e integración permanente, amplia y diversa con el estado, la empresa y la sociedad.', '5. Innovación en los procesos de Extensión y Proyección social aplicando metodologías con enfoque hacia la cooperación entre disciplinas, uso de nuevas tecnologías, en concordancia con la naturaleza de las distintas áreas de conocimiento.', 'Articulación con el sector productivo y sociedad', 'Gestión de alianzas, convenios y proyectos para el fomento del desarrollo sostenible según la agenda (ODS), regional e internacional', 'Incrementar en un 20% los ingresos del Centro de Investigaciones Científicas y Tecnológicas (CICIT) y Parque Tecnológico del Caribe (PTC) por servicios científicos y tecnológicos', 15.00, 'Impulsar la venta de servicios científicos y tecnológicos a través del CICIT', 20.00, 'Dpto. de Extens. y Proy. Social', 'PDI', '0', 'Tasa de variación de ingresos del CICIT y PTC para la vigencia de 10 años', '[(Ingresos por servicios científicos y tecnológicos del CICIT año 1 - Ingresos por servicios científicos y tecnológicos del CICIT año 0) / Ingresos por servicios científicos y tecnológicos del CICIT año 0) ] * 100', 'Anual', 'Porcentaje', 'Último valor reportado', '', '[]', '2%', 2, '0%', '2%', '2.00', '0.00', 0.00, 0.00, NULL, '', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
